mapper.update:
UPDATE feed_task
   SET task_status = #{nextStatus},
       next_run_at = #{nextRunAt},
       updated_at = #{updatedAt}
 WHERE id = #{id}
   AND deleted_at IS NULL
   AND task_status = #{expectedStatus}

UPDATE feed_task
   SET current_round_no = current_round_no + 1,
       next_run_at = #{nextRunAt},
       updated_at = #{now}
 WHERE id = #{id}
   AND deleted_at IS NULL
   AND status = 1
   AND task_status = 1
   AND next_run_at IS NOT NULL
   AND next_run_at <= #{now}

UPDATE feed_task
   SET next_run_at = #{nextRunAt},
       updated_at = #{updatedAt}
 WHERE id = #{id}
   AND deleted_at IS NULL
   AND task_status = 1

UPDATE feed_task
   SET total_account_num = total_account_num + #{delta},
       updated_at = #{updatedAt}
 WHERE id = #{id}
   AND deleted_at IS NULL

UPDATE feed_task
   SET success_account_num = success_account_num + 1,
       updated_at = #{updatedAt}
 WHERE id = #{id}
   AND deleted_at IS NULL

UPDATE feed_task
   SET failed_account_num = failed_account_num + 1,
       updated_at = #{updatedAt}
 WHERE id = #{id}
   AND deleted_at IS NULL
